<?php $pageTitle=$curso['titulo_curso'];$pageSubtitle=$curso['descripcion_curso'];require __DIR__.'/partials/header.php'; ?><div class="toolbar"><div><h2>Contenido del curso</h2><p>Instructor: <?=htmlspecialchars($curso['instructor'])?></p></div><?php if((int)$_SESSION['rol_id']===2): ?><a class="btn btn-primary" href="index.php?route=crear-evaluacion&curso=<?=$curso['id_curso']?>">+ Evaluación</a><?php endif; ?></div><div class="grid"><div class="panel" style="grid-column:1/-1"><h2>Módulos</h2><?php foreach($modulos as $m): ?><div class="card module"><h3><?=htmlspecialchars($m['nombre_modulo'])?></h3><?php foreach($m['lecciones'] as $l): ?><div class="lesson"><strong><?=htmlspecialchars($l['titulo_leccion'])?></strong><?php foreach($l['recursos'] as $r): ?> · <a target="_blank" href="<?=htmlspecialchars($r['ruta_archivo'])?>"><?=htmlspecialchars($r['nombre_recurso'])?></a><?php endforeach; ?></div><?php endforeach; ?><?php if((int)$_SESSION['rol_id']===2): ?><div class="actions"><form method="post" action="index.php?route=crear-leccion"><input type="hidden" name="curso" value="<?=$curso['id_curso']?>"><input type="hidden" name="modulo" value="<?=$m['id_modulo']?>"><input type="hidden" name="orden" value="<?=count($m['lecciones'])+1?>"><input class="search" name="titulo" placeholder="Nueva lección" required><button class="btn btn-secondary">Agregar lección</button></form></div><?php endif; ?></div><?php endforeach; ?><?php if((int)$_SESSION['rol_id']===2): ?><form method="post" action="index.php?route=crear-modulo" class="actions"><input type="hidden" name="curso" value="<?=$curso['id_curso']?>"><input type="hidden" name="orden" value="<?=count($modulos)+1?>"><input class="search" name="nombre" placeholder="Nuevo módulo" required><button class="btn btn-primary">Agregar módulo</button></form><?php endif; ?><?php if(!$modulos): ?><div class="empty">Este curso todavía no tiene módulos.</div><?php endif; ?></div><div class="panel" style="grid-column:1/-1"><h2>Evaluaciones</h2><?php foreach($evaluaciones as $e): ?><div class="list-item"><strong><?=htmlspecialchars($e['titulo_evaluacion'])?></strong> · <?=$e['preguntas']?> preguntas · aprobación <?=$e['puntaje_aprobacion']?><?php if((int)$_SESSION['rol_id']===2): ?> <a class="btn btn-secondary" href="index.php?route=crear-pregunta&evaluacion=<?=$e['id_evaluacion']?>">Agregar pregunta</a><?php else: ?> <a class="btn btn-primary" href="index.php?route=evaluacion&id=<?=$e['id_evaluacion']?>">Presentar</a><?php endif; ?></div><?php endforeach; ?><?php if(!$evaluaciones): ?><div class="empty">No hay evaluaciones disponibles.</div><?php endif; ?></div></div><?php require __DIR__.'/partials/footer.php'; ?>
